// For h=256*q+l, identical fixed-byte FNV suffix trajectories have identical
// low bytes at every step. Their difference is 256*q*P^72 modulo 2^64.
inline constexpr std::uint64_t runtimePathProfileHashFixedSuffix(
    std::uint64_t hash,bool passable) noexcept {
    const auto& table=passable?runtimePathProfileFixedSuffix1:runtimePathProfileFixedSuffix0;
    return (hash & ~std::uint64_t{255})*runtimePathProfileFnvPrimePower72
        +table[static_cast<std::size_t>(hash & 255U)];
}
template<class Node>
inline constexpr bool runtimePathProfileHasFixedSuffix(const Node& node) noexcept {
    return node.level==0 && !node.water && !node.shore && !node.bridge
        && !node.ramp && !node.cliff && node.cost==10 && node.hazardCost==0;
}
// This node helper is also the standalone oracle/benchmark entry. Queue
// dispatch retains all older reference branches outside its full-node loop.
template<class Node>
inline constexpr std::uint64_t runtimePathProfileHashFixedSuffixNode(
    std::uint64_t hash,std::int64_t key,const Node& node,bool reference=false) noexcept {
    if(!reference && runtimePathProfileHasFixedSuffix(node))
        return runtimePathProfileHashFixedSuffix(runtimePathProfileHashFast(hash,key),node.passable);
    if(!node.water && !node.shore && !node.bridge && !node.ramp && !node.cliff
        && node.hazardCost==0 && node.cost>=1 && node.cost<=255)
        return runtimePathProfileHashFlatDry(hash,key,node.level,node.passable,node.cost);
    hash=runtimePathProfileHashFast(hash,key);
    hash=runtimePathProfileHashFast(hash,node.level);
    hash=runtimePathProfileHashFast(hash,node.passable?1:0);
    hash=runtimePathProfileHashFast(hash,node.water?1:0);
    hash=runtimePathProfileHashFast(hash,node.shore?1:0);
    hash=runtimePathProfileHashFast(hash,node.bridge?1:0);
    hash=runtimePathProfileHashFast(hash,node.ramp?1:0);
    hash=runtimePathProfileHashFast(hash,node.cliff?1:0);
    hash=runtimePathProfileHashFast(hash,node.cost);
    return runtimePathProfileHashFast(hash,node.hazardCost);
}
